'use strict';

const { ExprError } = require('./errors');

/** Convert source to positioned tokens without repeatedly slicing its suffix. */
function tokenize(source) {
  const tokens = [];
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;
  while (offset < source.length) {
    const column = offset + 1;
    while (offset < source.length && /\s/.test(source[offset])) offset += 1;
    if (offset === source.length) break;
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      tokens.push({ type: 'number', value: Number(numeric[0]), column });
      offset = number.lastIndex;
      continue;
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      tokens.push({ type: 'identifier', value: name[0], column });
      offset = identifier.lastIndex;
      continue;
    }
    const pair = source.slice(offset, offset + 2);
    if (['**', '//', '<=', '>=', '==', '!='].includes(pair)) {
      tokens.push({ type: 'operator', value: pair, column });
      offset += 2;
    } else if ('+-*/%<>() ,'.includes(source[offset]) && source[offset] !== ' ') {
      tokens.push({ type: 'operator', value: source[offset], column });
      offset += 1;
    } else {
      throw new ExprError('Unexpected character', column);
    }
  }
  tokens.push({ type: 'eof', value: '', column: source.length + 1 });
  return tokens;
}

module.exports = { tokenize };
'use strict';

const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    let left = sum();
    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, sum());
    }
    return left;
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = power();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, power());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return primary();
  }

  function power() {
    let left = unary();
    while (is('**')) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      take();
      const args = [];
      if (!is(')')) {
        args.push(comparison());
        while (is(',')) {
          take();
          args.push(comparison());
        }
      }
      expect(')');
      if (!['min', 'max', 'abs'].includes(token.value)) {
        throw new ExprError('Unknown function', token.column);
      }
      if (!args.length || (token.value === 'abs' && args.length !== 1)) {
        throw new ExprError('Wrong argument count', token.column);
      }
      return { type: 'call', name: token.value, args };
    }
    if (token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };
