'use strict';

const { ExprError } = require('./errors');

const TWO_CHAR_OPERATORS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const ONE_CHAR_OPERATORS = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);

/**
 * Create a lazy lexer over source. Tokens are produced on demand so that the
 * parser reports the leftmost offending token: a syntax error is raised before
 * an invalid character that appears later in the source is ever scanned.
 * Each token's column is the 1-based UTF-16 offset of its first character.
 */
function createLexer(source) {
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  const whitespace = /\s*/y;
  let offset = 0;

  function next() {
    whitespace.lastIndex = offset;
    whitespace.exec(source);
    offset = whitespace.lastIndex;
    const column = offset + 1;
    if (offset >= source.length) return { type: 'eof', value: '', column: source.length + 1 };

    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      offset = number.lastIndex;
      return { type: 'number', value: Number(numeric[0]), column };
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      offset = identifier.lastIndex;
      return { type: 'identifier', value: name[0], column };
    }
    const pair = source.slice(offset, offset + 2);
    if (TWO_CHAR_OPERATORS.has(pair)) {
      offset += 2;
      return { type: 'operator', value: pair, column };
    }
    if (ONE_CHAR_OPERATORS.has(source[offset])) {
      offset += 1;
      return { type: 'operator', value: source[offset - 1], column };
    }
    throw new ExprError('Unexpected character', column);
  }

  return { next };
}

module.exports = { createLexer };

'use strict';

const { ExprError } = require('./errors');
const { createLexer } = require('./tokenizer');

const COMPARISON_OPERATORS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCT_OPERATORS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/**
 * Parse a complete formula into an AST, following the grammar documented in
 * index.js. Flat chains (sums, products, comparisons, call arguments, runs of
 * unary signs) are parsed with loops; only parentheses and ** recurse.
 * Nodes retain operator tokens so evaluation errors can report their columns.
 */
function parse(source) {
  const lexer = createLexer(source);
  let token = lexer.next();
  const advance = () => {
    const taken = token;
    token = lexer.next();
    return taken;
  };
  const isOperator = value => token.type === 'operator' && token.value === value;
  const isOneOf = set => token.type === 'operator' && set.has(token.value);
  const expect = value => {
    if (!isOperator(value)) throw new ExprError(`Expected ${value}`, token.column);
    return advance();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  // comparison := sum (cmp sum)*  -- a chain, not nested booleans.
  function comparison() {
    const first = sum();
    if (!isOneOf(COMPARISON_OPERATORS)) return first;
    const operands = [first];
    const operators = [];
    while (isOneOf(COMPARISON_OPERATORS)) {
      operators.push(advance());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  // sum := product (('+' | '-') product)*
  function sum() {
    let left = product();
    while (isOperator('+') || isOperator('-')) {
      const operator = advance();
      left = binary(operator, left, product());
    }
    return left;
  }

  // product := unary (('*' | '/' | '//' | '%') unary)*
  function product() {
    let left = unary();
    while (isOneOf(PRODUCT_OPERATORS)) {
      const operator = advance();
      left = binary(operator, left, unary());
    }
    return left;
  }

  // unary := ('+' | '-') unary | power  -- collected iteratively.
  function unary() {
    const signs = [];
    while (isOperator('+') || isOperator('-')) signs.push(advance());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  // power := primary ('**' unary)?  -- right associative via unary.
  function power() {
    const base = primary();
    if (!isOperator('**')) return base;
    const operator = advance();
    return binary(operator, base, unary());
  }

  function primary() {
    const start = token;
    if (start.type === 'number') {
      advance();
      return { type: 'number', value: start.value };
    }
    if (start.type === 'identifier') {
      advance();
      if (!isOperator('(')) return { type: 'variable', name: start.value, column: start.column };
      return call(start);
    }
    if (isOperator('(')) {
      advance();
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', start.column);
  }

  // Name and arity violations are reported at the function identifier as soon
  // as they become certain, so they win over any later syntax error.
  function call(name) {
    if (!FUNCTIONS.has(name.value)) throw new ExprError('Unknown function', name.column);
    advance(); // '('
    if (isOperator(')')) throw new ExprError('Wrong argument count', name.column);
    const args = [comparison()];
    while (isOperator(',')) {
      if (name.value === 'abs') throw new ExprError('Wrong argument count', name.column);
      advance();
      args.push(comparison());
    }
    expect(')');
    return { type: 'call', name: name.value, args };
  }

  const expression = comparison();
  if (token.type !== 'eof') throw new ExprError('Unexpected token', token.column);
  return expression;
}

module.exports = { parse };

'use strict';

const { ExprError } = require('./errors');

/** Python float floor division (CPython float_floor_div); zero is +0. */
function floorDivide(left, right) {
  const mod = left % right;
  let div = (left - mod) / right;
  if (mod && (right < 0) !== (mod < 0)) div -= 1;
  if (!div) return 0;
  let floored = Math.floor(div);
  if (div - floored > 0.5) floored += 1;
  return floored === 0 ? 0 : floored;
}

/** Python float modulo: result takes the divisor's sign; zero is +0. */
function modulo(left, right) {
  let mod = left % right;
  if (mod && (right < 0) !== (mod < 0)) mod += right;
  return mod === 0 ? 0 : mod;
}

/** Python float power where it differs from JS for finite real results. */
function power(left, right) {
  if (left === 1) return 1;
  if (left === -1 && (right === Infinity || right === -Infinity)) return 1;
  return left ** right;
}

/** Apply a binary or comparison operator token; booleans act as 0/1. */
function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '//': return floorDivide(left, right);
    case '%': return modulo(left, right);
    case '**': return power(left, right);
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/**
 * Evaluate with explicit frames, so long left-deep chains never recurse.
 * Children are always evaluated left to right; each variable occurrence is
 * read exactly once.
 */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
    if (node.type === 'number') {
      result = node.value;
      frames.pop();
    } else if (node.type === 'variable') {
      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
        throw new ExprError('Unknown variable', node.column);
      }
      result = variables[node.name];
      frames.pop();
    } else if (node.type === 'unary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operand, phase: 0 });
      } else {
        const operand = Number(result);
        result = node.operator.value === '-' ? -operand : operand;
        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
      // a < b <= c means (a < b) and (b <= c); stop at the first false link.
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operands[0], phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.index = 0;
        frame.phase = 2;
        frames.push({ node: node.operands[1], phase: 0 });
      } else {
        const right = result;
        if (!apply(node.operators[frame.index], frame.left, right)) {
          result = false;
          frames.pop();
        } else if (frame.index + 1 === node.operators.length) {
          result = true;
          frames.pop();
        } else {
          frame.left = right;
          frame.index += 1;
          frames.push({ node: node.operands[frame.index + 1], phase: 0 });
        }
      }
    } else if (node.type === 'call') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frame.index = 0;
        frames.push({ node: node.args[0], phase: 0 });
      } else {
        // Like Python, min/max keep the first extreme argument as-is (so
        // booleans stay booleans and NaN/-0 ordering matches); abs is numeric.
        if (frame.index === 0) {
          frame.value = result;
        } else if (node.name === 'min' ? Number(result) < Number(frame.value)
