  if (!div) return 0;
  let floored = Math.floor(div);
  if (div - floored > 0.5) floored += 1;
  return floored === 0 ? 0 : floored;
}

/** Python float modulo: result takes the divisor's sign; zero is +0. */
function modulo(left, right) {
  let mod = left % right;
  if (mod && (right < 0) !== (mod < 0)) mod += right;
  return mod === 0 ? 0 : mod;
